package edu.klh.soa.workflow;import edu.klh.soa.security.JwtGuard;import org.springframework.context.annotation.*;import org.springframework.boot.web.servlet.FilterRegistrationBean;@Configuration public class SecurityConfig {@Bean public FilterRegistrationBean<JwtGuard> jwtGuard(){FilterRegistrationBean<JwtGuard> b=new FilterRegistrationBean<>();b.setFilter(new JwtGuard());b.addUrlPatterns("/*");b.setOrder(1);return b;}}
